import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { buildImportPayload, parseIngStatement, type IngStatement } from "@/lib/import/ing";
import { importPayloadSchema } from "@/lib/import/schema";

// Oracle: test/fixtures/ing/expected.json (generated by scripts/fixture-ing.mjs, checked by fixture:check).
const FIXTURES = new URL("../fixtures/ing/", import.meta.url);
const MAIN = "Lista_transakcji_nr_0000123456_010926.csv";
const OVERLAP = "Lista_transakcji_nr_0000123457_011026-overlap.csv";
const NO_HEADER = "Lista_transakcji_nr_0000098765_011024-no-header.csv";
const CURRENCY = "Lista_transakcji_nr_0000099876_021124-currency.csv";
const MAIN_ACCOUNT = "11111100000000000000000001";
const VAT_ACCOUNT = "11111100000000000000000002";

interface ExpectedRow {
  file: string;
  line: number;
  bankTxId: string;
  account: string;
  occurredOn: string;
  amountMinor: number;
  traps: string[];
  imported: boolean;
}
interface Expected {
  files: Record<string, { imported: { count: number; sumMinor: number } }>;
  rows: ExpectedRow[];
}

const expected = JSON.parse(readFileSync(new URL("expected.json", FIXTURES), "utf8")) as Expected;
const bytesOf = (name: string) => new Uint8Array(readFileSync(new URL(name, FIXTURES)));
const mainRows = expected.rows.filter((r) => r.file === MAIN);

function parseOk(bytes: Uint8Array): IngStatement {
  const result = parseIngStatement(bytes);
  if (!result.ok) throw new Error(`expected ok, got ${result.error}`);
  return result.statement;
}

// Drops line `lineNo` (1-based) from the raw bytes, keeping the cp1250 encoding intact.
function withoutLine(bytes: Uint8Array, lineNo: number): Uint8Array {
  const starts = [0];
  bytes.forEach((b, i) => {
    if (b === 0x0a) starts.push(i + 1);
  });
  return Uint8Array.from([...bytes.subarray(0, starts[lineNo - 1]), ...bytes.subarray(starts[lineNo])]);
}

describe("parseIngStatement — main fixture", () => {
  const statement = parseOk(bytesOf(MAIN));

  it("reads both accounts, the D1 default and the preamble period", () => {
    expect(statement.accounts.map((a) => [a.name, a.number, a.rows])).toEqual([
      ["Rachunek Firmowy Główny", MAIN_ACCOUNT, 222],
      ["Rachunek VAT", VAT_ACCOUNT, 12],
    ]);
    expect(statement.defaultAccountNumber).toBe(MAIN_ACCOUNT);
    expect(statement.period).toEqual({ start: "2025-09-01", end: "2026-08-31" });
    expect(statement.rows).toHaveLength(234);
  });

  it("builds the default account payload that matches expected.json", () => {
    const payload = buildImportPayload(statement, MAIN_ACCOUNT);
    const imported = mainRows.filter((r) => r.imported);
    expect(payload.accountName).toBe("Rachunek Firmowy Główny");
    expect(payload.transactions).toHaveLength(206);
    expect(payload.transactions.reduce((s, t) => s + t.amountMinor, 0)).toBe(6497147);
    expect(payload.transactions.map((t) => [t.occurredOn, t.bankTxId, t.amountMinor])).toEqual(
      imported.map((r) => [r.occurredOn, r.bankTxId, Math.abs(r.amountMinor)]),
    );
    expect(expected.files[MAIN].imported).toEqual({ count: 206, sumMinor: 6497147 });
  });

  it("counts debits and credits per account", () => {
    const main = statement.accounts[0];
    expect(main.debits).toBe(206);
    expect(main.credits).toBe(main.rows - main.debits);
  });

  it("keeps the unescaped inner quote of T19 counterparties (lines 81, 148, 214)", () => {
    const t19 = mainRows.filter((r) => r.traps.includes("T19"));
    expect(t19.map((r) => r.line)).toEqual([81, 148, 214]);
    for (const r of t19) {
      const row = statement.rows.find((x) => x.bankTxId === r.bankTxId && x.account === MAIN_ACCOUNT);
      expect(row?.counterparty).toMatch(/^[^"]+"[^"]+"/);
      expect(row?.counterparty).toBe(row?.counterparty.trim());
    }
  });

  it("strips apostrophes from Nr transakcji and trims text fields", () => {
    for (const row of statement.rows) {
      expect(row.bankTxId).toMatch(/^\d{18}$/);
      for (const text of [row.counterparty, row.title, row.details]) expect(text).toBe(text.trim());
    }
  });

  it("builds a VAT account payload with only its own debits", () => {
    const payload = buildImportPayload(statement, VAT_ACCOUNT);
    const vatDebits = mainRows.filter((r) => r.account === "Rachunek VAT" && r.amountMinor < 0);
    expect(payload.transactions).toHaveLength(4);
    expect(payload.transactions.map((t) => [t.bankTxId, t.amountMinor])).toEqual(
      vatDebits.map((r) => [r.bankTxId, -r.amountMinor]),
    );
  });

  it("produces a payload that passes importPayloadSchema", () => {
    expect(importPayloadSchema.safeParse(buildImportPayload(statement, MAIN_ACCOUNT)).success).toBe(true);
    expect(importPayloadSchema.safeParse(buildImportPayload(statement, VAT_ACCOUNT)).success).toBe(true);
  });
});

describe("parseIngStatement — other fixtures and broken input", () => {
  it("parses the -overlap file (the rejection lives in the database)", () => {
    const statement = parseOk(bytesOf(OVERLAP));
    expect(statement.accounts.map((a) => a.number)).toEqual([MAIN_ACCOUNT]);
    expect(statement.period).toEqual({ start: "2026-08-01", end: "2026-09-30" });
    expect(statement.rows).toHaveLength(7);
  });

  it("rejects the -no-header file as unknown-format", () => {
    expect(parseIngStatement(bytesOf(NO_HEADER))).toEqual({ ok: false, error: "unknown-format" });
  });

  it("rejects the -currency file as wrong-currency", () => {
    expect(parseIngStatement(bytesOf(CURRENCY))).toEqual({ ok: false, error: "wrong-currency" });
  });

  it("rejects the main file missing one data row (Liczba transakcji mismatch)", () => {
    expect(parseIngStatement(withoutLine(bytesOf(MAIN), mainRows[5].line))).toEqual({
      ok: false,
      error: "unknown-format",
    });
  });

  it("rejects the main file re-saved as UTF-8", () => {
    const text = new TextDecoder("windows-1250").decode(bytesOf(MAIN));
    expect(parseIngStatement(new TextEncoder().encode(text))).toEqual({ ok: false, error: "unknown-format" });
  });

  it("rejects random bytes and a non-ING UTF-8 text", () => {
    let seed = 42;
    const random = Uint8Array.from({ length: 4096 }, () => (seed = (Math.imul(seed, 1103515245) + 12345) >>> 0) >>> 24);
    expect(parseIngStatement(random)).toEqual({ ok: false, error: "unknown-format" });
    const other = new TextEncoder().encode("2026-09-01,2026-03-01,'61109010140000071219812874,Jan Kowalski,PLN\n");
    expect(parseIngStatement(other)).toEqual({ ok: false, error: "unknown-format" });
    expect(parseIngStatement(new Uint8Array())).toEqual({ ok: false, error: "unknown-format" });
  });
});

describe("buildImportPayload", () => {
  it("throws for an account that is not in the statement", () => {
    const statement = parseOk(bytesOf(MAIN));
    expect(() => buildImportPayload(statement, "0".repeat(26))).toThrow();
  });
});
